int cmp_int(const void* a, const void* b) {
    int x = *(const int*)a;
    int y = *(const int*)b;
    return (x > y) - (x < y);
}

int** threeSum(int* nums, int numsSize, int* returnSize, int** returnColumnSizes) {
    *returnSize = 0;
    *returnColumnSizes = NULL;
    if (numsSize < 3) return NULL;
    qsort(nums, numsSize, sizeof(int), cmp_int);
    // allocate an initial capacity for results
    int cap = 16;
    int** res = (int**)malloc(cap * sizeof(int*));
    int* cols = (int*)malloc(cap * sizeof(int));

    for (int i = 0; i < numsSize - 2; ++i) {
        if (i > 0 && nums[i] == nums[i-1]) continue; // skip duplicates for first element
        int left = i + 1, right = numsSize - 1;
        while (left < right) {
            long sum = (long)nums[i] + nums[left] + nums[right];
            if (sum == 0) {
                if (*returnSize >= cap) {
                    cap *= 2;
                    res = (int**)realloc(res, cap * sizeof(int*));
                    cols = (int*)realloc(cols, cap * sizeof(int));
                }
                int* trip = (int*)malloc(3 * sizeof(int));
                trip[0] = nums[i]; trip[1] = nums[left]; trip[2] = nums[right];
                res[*returnSize] = trip;
                cols[*returnSize] = 3;
                (*returnSize)++;
                // move left and right skipping duplicates
                int curL = nums[left], curR = nums[right];
                while (left < right && nums[left] == curL) left++;
                while (left < right && nums[right] == curR) right--;
            } else if (sum < 0) {
                left++;
            } else {
                right--;
            }
        }
    }
    *returnColumnSizes = cols;
    return res;
}

