    // strip outer array brackets
    size_t p = inner.find('[');
    size_t q = inner.rfind(']');
    if (p == string::npos || q == string::npos || q <= p) { cout << "[]\n"; return 0; }
    string arr = inner.substr(p+1, q-p-1);
    vector<int> nums;
    string token;
    for (size_t i = 0; i < arr.size(); ++i) {
        char c = arr[i];
        if (c == ',') {
            if (!token.empty()) { nums.push_back(stoi(token)); token.clear(); }
        } else if (!isspace((unsigned char)c)) token.push_back(c);
    }
    if (!token.empty()) nums.push_back(stoi(token));
    auto res = Solution().threeSum(nums);
    cout << "[";
    for (size_t i = 0; i < res.size(); ++i) {
        cout << "[" << res[i][0] << "," << res[i][1] << "," << res[i][2] << "]";
        if (i + 1 < res.size()) cout << ",";
    }
    cout << "]\n";
